                style={{ fill: bgColor }}
            />
        </svg>
    ) : (
        <svg {...wrapProps}>
            <path
                d="M0.5 0L1.5 0C1.5 4, 3 5.5, 5 7.5S8,10 8,12S7 14.5, 5 16.5S1.5,20 1.5,24L0.5 24L0.5 0z"
