export default class TableRow extends BaseComponent<BaseRowProps, Record<string, any>> {
    static propTypes = baseRowPropTypes;

    static defaultProps = {
        columns: [] as [],
        rowExpandable: stubTrue,
        components: {
            body: {
                row: 'tr',
                cell: 'td',
            },
        },
        prefixCls: cssClasses.PREFIX,
        onRow: noop,
        onRowClick: noop,
        onRowDoubleClick: noop,
        onRowMouseEnter: noop,
        onRowMouseLeave: noop,
        onHover: noop,
        onDidUpdate: noop,
        visible: true,
        hovered: false,
        selected: false,
        disabled: false,
    };

    get adapter(): TableRowAdapter<BaseRowProps> {
        return {
            ...super.adapter,
            notifyClick: (...args) => this.props.onRowClick(...args),
            notifyDoubleClick: (...args) => this.props.onRowDoubleClick(...args),
            notifyMouseLeave: (...args) => {
                this.props.onHover(false, this.props.rowKey);
                this.props.onRowMouseEnter(...args);
            },
            notifyMouseEnter: (...args) => {
                this.props.onHover(true, this.props.rowKey);
                this.props.onRowMouseEnter(...args);
            },
        };
    }

    constructor(props: BaseRowProps) {
        super(props);
        this.foundation = new TableRowFoundation(this.adapter);
    }

    componentDidMount() {
        // fix #745
        // didmount/willUnmount may be called twice when React.StrictMode is true in React 18, we need to ensure that this.cache.customRowProps is correct
        const {
            onRow,
            index,
            record,
        } = this.props;
        const customRowProps = this.adapter.getCache('customRowProps');
        if (typeof customRowProps === 'undefined') {
            const { className: customClassName, style: customStyle, ...rowProps } = onRow(record, index) || {};
            this.adapter.setCache('customRowProps', { ...rowProps });
        }
    }

    shouldComponentUpdate(nextProps: BaseRowProps) {
        /**
          * Shallow comparison of incoming props to simulate PureComponent
          * Deep comparison cellWidths
          *
          * 浅层对比传入的 props，模拟 PureComponent
          * 深比较 cellWidths
          */
        const omitProps = ['cellWidths'];
        const isPropsShallowEqual = shallowEqualObjects(omit(nextProps, omitProps), omit(this.props, omitProps));
        if (!isPropsShallowEqual || !isEqual(pick(nextProps, omitProps), pick(this.props, omitProps))) {
            return true;
        }
        return false;
    }

    // Pass true to render the tree-shaped expand button
    renderExpandIcon = (record: Record<string, any>) => {
        const { renderExpandIcon } = this.props;
        return renderExpandIcon(record, true);
    };

    renderCells() {
        const {
            columns,
            record,
            index,
            prefixCls,
            fixed,
            components,
            expandableRow,
            level,
            expandIcon,
            rowExpandable,
            isSection,
            expandedRow,
            virtualized,
            indentSize,
            hideExpandedColumn,
            cellWidths,
            selected,
            expanded,
            disabled,
            onDidUpdate,
        } = this.props;

        const BodyCell = get(components, 'body.cell', strings.DEFAULT_COMPONENTS.body.cell);

        const cells: ReactNode[] = [];
        const displayExpandedColumn = rowExpandable(record);

        let firstIndex = 0;
        // const dataColumns = getDataColumns(columns);

        each(columns, (column, columnIndex) => {
            const columnKey = get(column, 'key');
            const expandableProps: { renderExpandIcon?: (record: Record<string, any>) => ReactNode; expandIcon?: ExpandIcon; indent?: number } = {};

            if (fixed !== 'right') {
                if (isInnerColumnKey(columnKey)) {
                    firstIndex++;
                }

                if (expandableRow && columnIndex === firstIndex) {
                    expandableProps.renderExpandIcon = this.renderExpandIcon;
                    if (hideExpandedColumn || isSection) {
                        expandableProps.expandIcon = expandIcon != null ? expandIcon : true;
                    }
                }

                // Only the first data row will be indented
                if (level != null && columnIndex === firstIndex) {
                    expandableProps.indent = level;
                    const isBool = typeof expandIcon === 'boolean';
                    const hasExpandIcon = expandIcon !== false || !isBool && expandIcon !== null;

                    // 如果 expandIcon 为空，不需要 indent
                    if (!expandableRow && hideExpandedColumn && hasExpandIcon) {
                        expandableProps.indent = level + 1;
                    }
                }
            }

            if (isExpandedColumn(column) && !displayExpandedColumn) {
                cells.push(<TableCell key={columnIndex} colIndex={columnIndex} isSection={isSection} />);
            } else if (!isScrollbarColumn(column)) {
                const diyProps: { width?: number } = {};

                if (BodyCell !== strings.DEFAULT_COMPONENTS.body.cell && virtualized && !expandedRow) {
                    diyProps.width = get(cellWidths, columnIndex);
                }

                cells.push(
                    <TableCell
                        colIndex={columnIndex}
                        {...expandableProps}
                        {...diyProps}
                        hideExpandedColumn={hideExpandedColumn}
                        indentSize={indentSize}
                        isSection={isSection}
                        prefixCls={`${prefixCls}`}
                        column={column}
                        key={columnIndex}
                        index={index}
                        record={record}
                        component={BodyCell}
                        fixedLeft={isFixedLeft(column) && arrayAdd(cellWidths, 0, columnIndex)}
                        lastFixedLeft={isLastLeftFixed(columns, column)}
                        fixedRight={isFixedRight(column) && arrayAdd(cellWidths, columnIndex + 1)}
                        firstFixedRight={isFirstFixedRight(columns, column)}
                        selected={selected}
                        expanded={expanded}
                        disabled={disabled}
                        onDidUpdate={onDidUpdate}
                    />
                );
            }
        });

        return cells;
    }

    handleMouseEnter = (e: React.MouseEvent) => {
        this.foundation.handleMouseEnter(e);

        const customRowProps = this.adapter.getCache('customRowProps');

        if (typeof customRowProps?.onMouseEnter === 'function') {
            customRowProps.onMouseEnter(e);
        }
    };

    handleMouseLeave = (e: React.MouseEvent) => {
        this.foundation.handleMouseLeave(e);

        const customRowProps = this.adapter.getCache('customRowProps');

        if (typeof customRowProps?.onMouseLeave === 'function') {
            customRowProps.onMouseLeave(e);
        }
    };

    handleClick = (e: React.MouseEvent) => {
        this.foundation.handleClick(e);

        const customRowProps = this.adapter.getCache('customRowProps');

        if (customRowProps && typeof customRowProps.onClick === 'function') {
            customRowProps.onClick(e);
        }
    };

    render() {
        const { style } = this.props;
        const {
            components,
            prefixCls,
            selected,
            onRow,
            index,
            className,
            replaceClassName,
            record,
            hovered,
            expanded,
            displayNone,
            expandableRow,
            level,
            expandedRow,
            isSection,
            rowKey
        } = this.props;

        const BodyRow = components.body.row;

        const { className: customClassName, style: customStyle, ...rowProps } = onRow(record, index) || {};

        this.adapter.setCache('customRowProps', { ...rowProps });

        const baseRowStyle = { ...style, ...customStyle };

        const rowCls =
            typeof replaceClassName === 'string' && replaceClassName.length
                ? classnames(replaceClassName, customClassName)
                : classnames(
                    className,
                    `${prefixCls}-row`,
                    {
                        [`${prefixCls}-row-selected`]: selected,
                        [`${prefixCls}-row-expanded`]: expanded,
                        [`${prefixCls}-row-hovered`]: hovered,
                        [`${prefixCls}-row-hidden`]: displayNone,
                    },
                    customClassName
                );
        const ariaProps = {};
        if (typeof index === 'number') {
            ariaProps['aria-rowindex'] = index + 1;
        }
        if (expandableRow) {
            ariaProps['aria-expanded'] = expanded;
        }
        // if row is expandedRow, set it's level to 2 
        if (expanded || expandedRow) {
            ariaProps['aria-level'] = 2;
        }
        if (typeof level === 'number') {
            ariaProps['aria-level'] = level + 1;
        }
        if (isSection) {
            ariaProps['aria-level'] = 1;
        }

        return (
            <BodyRow
                role="row"
                {...ariaProps}
                {...rowProps}
                style={baseRowStyle}
                className={rowCls}
                // used for dnd-kit sortable
                data-row-key={rowKey}
                onMouseEnter={this.handleMouseEnter}
                onMouseLeave={this.handleMouseLeave}
                onClick={this.handleClick}
            >
                {this.renderCells()}
            </BodyRow>
        );
    }
}

export type RenderExpandIcon = (record: Record<string, any>, isNested: boolean) => ReactNode | null;

import React, { PureComponent, isValidElement, ReactNode } from 'react';
import PropTypes from 'prop-types';
import classnames from 'classnames';
import { get, set, isNull } from 'lodash';

import { cssClasses, strings } from '@douyinfe/semi-foundation/table/constants';
import { arrayAdd, filterColumns } from '@douyinfe/semi-foundation/table/utils';
import Store from '@douyinfe/semi-foundation/utils/Store';
import TableContext, { TableContextProps } from '../table-context';
import TableRow from './BaseRow';
import { amendTableWidth } from '../utils';
import { ColumnProps, ExpandIcon, TableComponents, Virtualized, Fixed } from '../interface';

export interface TableExpandedRowProps {
    cellWidths: number[]; // required
    className?: string;
    columns?: ColumnProps[];
    components?: TableComponents;
    defaultExpandAllRows?: boolean;
    defaultExpandedRowKeys?: (string | number)[];
    expandIcon?: ExpandIcon;
    expandRowByClick?: boolean;
    expanded?: boolean;
    expandedRowKeys?: (string | number)[];
    expandedRowRender?: (record?: Record<string, any>, index?: number, expanded?: boolean) => ExpandedRowRenderReturnType;
    indentSize?: number;
    index?: number;
    prefixCls?: string;
    record?: Record<string, any>;
    renderExpandIcon?: (record?: Record<string, any>, isNested?: boolean) => ReactNode | null;
    store?: Store;
    style?: React.CSSProperties;
    virtualized?: Virtualized
    displayNone?: boolean;
}

/**
 * Render expanded row
 */
export default class TableExpandedRow extends PureComponent<TableExpandedRowProps> {
    static contextType = TableContext;

    static propTypes = {
        cellWidths: PropTypes.array.isRequired,
        className: PropTypes.string,
        columns: PropTypes.array,
        components: PropTypes.object,
        defaultExpandAllRows: PropTypes.bool,
        defaultExpandedRowKeys: PropTypes.array,
        expandIcon: PropTypes.oneOfType([PropTypes.object, PropTypes.node, PropTypes.func]),
        expandRowByClick: PropTypes.bool,
        expanded: PropTypes.bool,
        expandedRowKeys: PropTypes.array,
        expandedRowRender: PropTypes.func,
        indentSize: PropTypes.number,
        index: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
        onExpand: PropTypes.func,
        onExpandedRowsChange: PropTypes.func,
        prefixCls: PropTypes.string,
        record: PropTypes.object,
        renderExpandIcon: PropTypes.func,
        store: PropTypes.object,
        style: PropTypes.object,
        virtualized: PropTypes.oneOfType([PropTypes.bool, PropTypes.object]),
    };
    static defaultProps = {
        record: {},
        prefixCls: cssClasses.PREFIX,
    };

    context: TableContextProps;

    render() {
        const {
            record,
            columns: propColumns = [],
            prefixCls,
            className,
            expanded,
            expandedRowRender,
            renderExpandIcon,
            index,
            store,
            components,
            style,
            virtualized,
            indentSize,
            cellWidths,
            displayNone
        } = this.props;
        const { tableWidth, anyColumnFixed, getCellWidths } = this.context;
        const cell: ExpandedRowRenderReturnType = expandedRowRender(record, index, expanded);
        let children: ReactNode = null;
        const props: { colSpan?: number; style?: Record<string, any> } = {};
        let column = {};
        if (isNull(cell)) {
            return null;
        } else if (isValidElement(cell)) {
            children = cell;
        } else if (cell && Object.prototype.toString.call(cell) === '[object Object]') {
            const { children: cellChildren, fixed, ...restProps } = cell as { children: ReactNode; fixed: Fixed };
            children = cellChildren;
            column = { ...restProps };
        }

        if (get(components, 'body.cell') !== strings.DEFAULT_COMPONENTS.body.cell) {
            if (virtualized) {
                set(props, 'style.height', '100%');
            }
            set(props, 'style.display', 'block');
            set(props, 'style.width', arrayAdd(cellWidths, 0, propColumns.length));
        } else {
            // Remove the row where the scroll bar is located
            props.colSpan = filterColumns(propColumns).length;
        }

        const columns = [
            {
                render: () => ({
                    props,
                    children: (
                        <div
                            className={classnames(`${prefixCls}-expand-inner`)}
                            style={{
                                width: anyColumnFixed ? amendTableWidth(tableWidth) : undefined,
                            }}
                        >
                            {children}
                        </div>
                    ),
                }),
                ...column,
            },
        ];

        const rowCls = classnames(className, `${prefixCls}-row-expand`);
        const baseRowCellWidths = getCellWidths(columns);

        return (
            <TableRow
                style={style}
                components={components}
                className={rowCls}
                expandedRow={true}
                renderExpandIcon={renderExpandIcon}
                rowKey={`${record.key}-expanded-row`}
                columns={columns}
                store={store}
                virtualized={virtualized}
                indentSize={indentSize}
                cellWidths={baseRowCellWidths}
                displayNone={displayNone}
            />
        );
    }
}

export type ExpandedRowRenderReturnType = React.ReactNode | { children: ReactNode; fixed: Fixed } & ColumnProps;

import React, { PureComponent, isValidElement, ReactNode } from 'react';
import PropTypes from 'prop-types';
import classnames from 'classnames';
import { get, isSet } from 'lodash';

import Store from '@douyinfe/semi-foundation/utils/Store';
import { cssClasses, strings } from '@douyinfe/semi-foundation/table/constants';
import { filterColumns } from '@douyinfe/semi-foundation/table/utils';
import BaseRow from './BaseRow';
import TableContext, { TableContextProps } from '../table-context';
import {
    ColumnProps,
    RenderGroupSection,
    OnGroupedRow,
    TableComponents,
    Virtualized,
    RowKey,
    OnRowReturnObject
} from '../interface';

export interface SectionRowProps {
    record?: Record<string, any>;
    index?: number;
    columns?: ColumnProps[];
    group?: (string | number)[];
    groupKey: string | number;
    data?: Record<string, any>[];
    renderGroupSection?: RenderGroupSection; // render group title
    onGroupedRow?: OnGroupedRow<Record<string, any>>;
    clickGroupedRowToExpand?: boolean;
    components?: TableComponents;
    expanded?: boolean;
    prefixCls?: string;
    onExpand?: (willExpanded: boolean, groupKey: number | string, e: React.MouseEvent) => void;
    virtualized?: Virtualized;
    style?: React.CSSProperties;
    renderExpandIcon?: (record: Record<string, any>, isNested: boolean, groupKey: string | number) => ReactNode | null;
    className?: string;
    store?: Store;
    rowKey?: RowKey<any>
}

/**
 * avoid affected by https://www.npmjs.com/package/babel-plugin-transform-react-remove-prop-types
 */
export const sectionRowPropTypes = {
    record: PropTypes.object,
    index: PropTypes.number,
    columns: PropTypes.array,
    group: PropTypes.object.isRequired,
    groupKey: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
    data: PropTypes.array,
    renderGroupSection: PropTypes.func, // render group title
    onGroupedRow: PropTypes.func,
    clickGroupedRowToExpand: PropTypes.bool,
    components: PropTypes.object,
    expanded: PropTypes.bool,
    prefixCls: PropTypes.string,
    onExpand: PropTypes.func,
    virtualized: PropTypes.oneOfType([PropTypes.bool, PropTypes.object]),
    style: PropTypes.object,
    renderExpandIcon: PropTypes.func, // passing to baseRow
    className: PropTypes.string,
    store: PropTypes.object,
    rowKey: PropTypes.oneOfType([PropTypes.string, PropTypes.number, PropTypes.func]),
};

/**
 * Grouping component title row
 */
class SectionRow extends PureComponent<SectionRowProps> {
    static contextType = TableContext;
    static propTypes = sectionRowPropTypes;

    static defaultProps = {
        prefixCls: cssClasses.PREFIX,
        components: {
            body: {
                row: 'tr',
                cell: 'td',
            },
        },
    };

    context: TableContextProps;

    onRow = (...args: any[]): OnRowReturnObject => {
        const { onGroupedRow, clickGroupedRowToExpand, onExpand, groupKey, expanded } = this.props;
        const rowProps: { onClick?: (e: React.MouseEvent) => void } = {};

        if (typeof onGroupedRow === 'function') {
            Object.assign(rowProps, onGroupedRow(...args));
        }

        return {
            ...rowProps,
            onClick: (e: React.MouseEvent) => {
                if (typeof onExpand === 'function' && clickGroupedRowToExpand) {
                    onExpand(!expanded, groupKey, e);
                }

                if (typeof rowProps.onClick === 'function') {
                    rowProps.onClick(e);
                }
            },
        };
    };

    collectGroupedData = () => {
        const { data, group, rowKey } = this.props;

        if (Array.isArray(data) && data.length && isSet(group)) {
            return data.filter(record => {
                const realRowKey = typeof rowKey === 'function' ? rowKey(record) : get(record, rowKey);
                return realRowKey != null && realRowKey !== '' && group.has(realRowKey);
            });
        }

        return [];
    };

    renderExpandIcon = (record: any) => {
        const { renderExpandIcon, groupKey } = this.props;

        if (typeof renderExpandIcon === 'function') {
            return renderExpandIcon(record, false, groupKey);
        }
        return null;
    };

    isInnerColumnKey(key: any) {
        if (key != null) {
            return [strings.DEFAULT_KEY_COLUMN_EXPAND, strings.DEFAULT_KEY_COLUMN_SELECTION].includes(key);
        }

        return false;
    }

    render() {
        const {
            record,
            columns: propColumns = [],
            prefixCls,
            className,
            expanded,
            renderGroupSection,
            components,
            index,
            store,
            group,
            groupKey,
            virtualized,
            style,
        } = this.props;

        const props: { colSpan?: number } = {};
        let column = {};
        let children: ReactNode = null;
        // render title
        const cell = typeof renderGroupSection === 'function' ? renderGroupSection(groupKey, [...group]) : null;

        if (isValidElement(cell)) {
            children = cell;
        } else if (cell && Object.prototype.toString.call(cell) === '[object Object]') {
            const { children: cellChildren, ...restProps } = cell as { children?: ReactNode };
            children = cellChildren;
            column = { ...restProps };
        }

        // Filter out scroll-bar column
        props.colSpan = filterColumns(propColumns).length;

        const columns = [{ render: () => ({ props, children }), ...column }];

        const rowCls = classnames(className, `${prefixCls}-row-section`, {
            on: expanded,
        });

        const { getCellWidths } = this.context;
        const baseRowCellWidths = getCellWidths(columns, null, true);

        return (
            <BaseRow
                components={components}
                virtualized={virtualized}
                index={index}
                onRow={this.onRow}
                expanded={expanded}
                expandIcon
                isSection
                record={record}
                replaceClassName={rowCls}
                expandableRow
                renderExpandIcon={this.renderExpandIcon}
                rowKey={groupKey}
                columns={columns}
                store={store}
                style={style}
                cellWidths={baseRowCellWidths}
            />
        );
    }
}

export default SectionRow;

