    const dropdownProps: DropdownProps = {
        ...props,
        onVisibleChange: (visible: boolean) => onFilterDropdownVisibleChange(visible),
        trigger,
        position,
        render,
    };

    if (filterDropdownVisible != null) {
        dropdownProps.visible = filterDropdownVisible;
